package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.inventory.*;
import com.intermarche.backoffice.engine.stock.TemporalStockService;
import com.intermarche.backoffice.domain.util.DateTimeProvider;
import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;
import io.restassured.response.Response;import jakarta.inject.Inject;import org.junit.jupiter.api.Test;
import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static io.restassured.RestAssured.given;
@QuarkusTest
@jakarta.enterprise.inject.Typed(InventoryCountingWorkflowTest.class)
class InventoryCountingWorkflowTest extends MissionCoordinationTest {
 @Inject TemporalStockService stocks;
 record Counting(Long order,Long execution,Long account,Map<String,Object> session){}
 Response inventory(String token,String method,String path,Object body){var r=given().auth().oauth2(token).contentType("application/json");if(body!=null)r.body(body);var v=r.request(method,"/inventories"+path);if(v.statusCode()>=400)System.out.println(path+" "+v.asString());return v;}
 Counting start(){Long account=QuarkusTransaction.requiringNew().call(()->{var a=stocks.account(f.store(),f.product());stocks.adjust(a.id,f.location(),key(),BigDecimal.TEN,DateTimeProvider.now());return a.id;});var body=Map.of("storeId",f.store(),"buildingId",f.building(),"scopeKind","BAY","area","Z","aisle","A","bay","1","start",DateTimeProvider.now().plusHours(1).toString(),"end",DateTimeProvider.now().plusHours(2).toString(),"requestKey",key(),"blind",true);long order=inventory(f.manager(),"POST","",body).then().statusCode(200).extract().jsonPath().getLong("id");Map<String,Object> reserve=Map.of("storeId",f.store(),"orderId",order,"requestKey",key(),"action","RESERVE");long execution=command(reserve).then().statusCode(200).extract().jsonPath().getLong("orders[0].executions[0].id");Map<String,Object> start=Map.of("storeId",f.store(),"executionId",execution,"requestKey",key(),"action","START_INVENTORY");Map<String,Object> s=command(start).then().statusCode(200).extract().jsonPath().getMap("inventory");return new Counting(order,execution,account,s);}
 Map<String,Object> count(Counting c,Map<String,Object> s,Object quantity,String state){var line=((List<Map<String,Object>>)s.get("lines")).getFirst();var body=new LinkedHashMap<String,Object>(Map.of("storeId",f.store(),"sessionId",((Number)s.get("id")).longValue(),"lineId",((Number)line.get("id")).longValue(),"expectedRevision",s.get("revision"),"requestKey",key(),"state",state));if(quantity!=null)body.put("quantity",quantity);return body;}
 Map<String,Object> submit(Map<String,Object> s){return inventory(f.picker(),"POST","/sessions/submit",Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");}
 void total(Long account,int expected){QuarkusTransaction.requiringNew().run(()->assertEquals(0,BigDecimal.valueOf(expected).compareTo(stocks.availability(account,null,DateTimeProvider.now()).physical)));}
 @Test void inventoryGraphqlResolvesBuildingForListAndDetailsAfterTransaction(){var c=start();String selection="id code building { id buildingCode } assignee { id badgeId } store { id code }";for(String query:List.of("{ inventoryOrder(id:"+c.order+") { "+selection+" } }","{ inventoryOrdersByDateRange(start:\""+DateTimeProvider.now().toLocalDate().atStartOfDay()+"\",end:\""+DateTimeProvider.now().plusDays(2)+"\") { "+selection+" } }")){var result=given().auth().oauth2(f.manager()).contentType("application/json").body(Map.of("query",query)).post("/graphql").then().statusCode(200).extract();assertNull(result.path("errors"),result.asString());assertTrue(result.asString().contains("buildingCode"),result.asString());}}
 @Test void zeroUnknownAndUncountedRemainDistinctAndReplayDoesNotDuplicateObservation(){var c=start();var s=c.session;assertNull(((List<Map<String,Object>>)s.get("lines")).getFirst().get("referenceQuantity"));var zero=count(c,s,0,"COUNTED");s=inventory(f.picker(),"POST","/counts",zero).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");inventory(f.picker(),"POST","/counts",zero).then().statusCode(200);assertEquals(0,new BigDecimal(((List<Map<String,Object>>)s.get("lines")).getFirst().get("quantity").toString()).signum());var unknown=count(c,s,null,"UNKNOWN");s=inventory(f.picker(),"POST","/counts",unknown).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");assertNull(((List<Map<String,Object>>)s.get("lines")).getFirst().get("quantity"));var invalid=count(c,s,0,"UNKNOWN");inventory(f.picker(),"POST","/counts",invalid).then().statusCode(400);total(c.account,10);QuarkusTransaction.requiringNew().run(()->assertEquals(2,InventoryCountObservation.count("line.session.id",((Number)c.session.get("id")).longValue())));}
 @Test void aRealMovementBetweenCountsIsIntegratedInsteadOfBecomingASecondDifference(){var c=start();var s=inventory(f.picker(),"POST","/counts",count(c,c.session,5,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=submit(s);assertEquals("RECOUNT_REQUIRED",s.get("state"));QuarkusTransaction.requiringNew().run(()->stocks.adjust(c.account,f.location(),key(),BigDecimal.valueOf(-2),DateTimeProvider.now()));s=inventory(f.picker(),"POST","/sessions/recount",Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=inventory(f.picker(),"POST","/counts",count(c,s,3,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=submit(s);assertEquals("SUBMITTED",s.get("state"));var managed=inventory(f.manager(),"GET","/sessions/"+s.get("id")+"?storeId="+f.store(),null).then().statusCode(200).extract();assertEquals(0,new BigDecimal("-5").compareTo(new BigDecimal(managed.jsonPath().getString("lines[0].variance"))));total(c.account,8);}
 @Test void contradictoryCountsRequireAnExplicitManagerDecision(){var c=start();var s=inventory(f.picker(),"POST","/counts",count(c,c.session,5,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=submit(s);s=inventory(f.picker(),"POST","/sessions/recount",Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=inventory(f.picker(),"POST","/counts",count(c,s,6,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");assertEquals("DISPUTED",submit(s).get("state"));total(c.account,10);}
 Map<String,Object> approval(Map<String,Object> s){var review=inventory(f.manager(),"GET","/sessions/"+s.get("id")+"/review?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");return inventory(f.manager(),"POST","/sessions/approve",Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key(),"reviewToken",review.get("reviewToken"),"reason","Contrôle physique contradictoire vérifié")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");}
 @Test void approvedRecountAppliesExactlyOnceWithoutRewritingObservations(){var c=start();var s=inventory(f.picker(),"POST","/counts",count(c,c.session,5,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=submit(s);s=inventory(f.picker(),"POST","/sessions/recount",Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=inventory(f.picker(),"POST","/counts",count(c,s,5,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=approval(submit(s));total(c.account,10);var apply=Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key());assertEquals("APPLIED",inventory(f.manager(),"POST","/sessions/apply",apply).then().statusCode(200).extract().path("state"));inventory(f.manager(),"POST","/sessions/apply",apply).then().statusCode(200);total(c.account,5);QuarkusTransaction.requiringNew().run(()->assertEquals(2,InventoryCountObservation.count("line.session.handlingOrder.id",c.order)));}
 @Test void movementAfterApprovalRequiresFreshApproval(){var c=start();var s=inventory(f.picker(),"POST","/counts",count(c,c.session,10,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=approval(submit(s));QuarkusTransaction.requiringNew().run(()->stocks.adjust(c.account,f.location(),key(),BigDecimal.valueOf(-2),DateTimeProvider.now()));inventory(f.manager(),"POST","/sessions/apply",Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key())).then().statusCode(409);s=approval(s);inventory(f.manager(),"POST","/sessions/apply",Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key())).then().statusCode(200);total(c.account,8);}

 @Test void targetedFreezeBlocksOnlyUntilManagerCancellationAndNeverChangesPhysical(){QuarkusTransaction.requiringNew().run(()->{var policy=new InventoryControlPolicy();policy.store=com.intermarche.backoffice.domain.store.Store.findById(f.store());policy.bayMovementMode="TARGETED_FREEZE";policy.persist();});var c=start();assertThrows(RuntimeException.class,()->QuarkusTransaction.requiringNew().run(()->stocks.adjust(c.account,f.location(),key(),BigDecimal.ONE.negate(),DateTimeProvider.now())));total(c.account,10);inventory(f.picker(),"POST","/sessions/cancel",Map.of("storeId",f.store(),"sessionId",c.session.get("id"),"expectedRevision",c.session.get("revision"),"requestKey",key(),"reason","Annulation")).then().statusCode(403);inventory(f.manager(),"POST","/sessions/cancel",Map.of("storeId",f.store(),"sessionId",c.session.get("id"),"expectedRevision",c.session.get("revision"),"requestKey",key(),"reason","Contrôle reporté")).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->stocks.adjust(c.account,f.location(),key(),BigDecimal.ONE.negate(),DateTimeProvider.now()));total(c.account,9);}
 @Test void bookCorrectionBetweenCountsDoesNotBecomeAPhysicalMovement(){var c=start();var s=inventory(f.picker(),"POST","/counts",count(c,c.session,5,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=submit(s);QuarkusTransaction.requiringNew().run(()->stocks.setPhysical(c.account,f.location(),key(),BigDecimal.TEN,BigDecimal.valueOf(5),"Autre contrôle approuvé"));s=inventory(f.picker(),"POST","/sessions/recount",Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=inventory(f.picker(),"POST","/counts",count(c,s,5,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");s=approval(submit(s));inventory(f.manager(),"POST","/sessions/apply",Map.of("storeId",f.store(),"sessionId",s.get("id"),"expectedRevision",s.get("revision"),"requestKey",key())).then().statusCode(200);total(c.account,5);}

 @Test void managerCanRetainTheFirstContradictoryCountWithoutAveragingOrEditingObservations(){var c=start();var first=inventory(f.picker(),"POST","/counts",count(c,c.session,5,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");first=submit(first);var next=inventory(f.picker(),"POST","/sessions/recount",Map.of("storeId",f.store(),"sessionId",first.get("id"),"expectedRevision",first.get("revision"),"requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");next=inventory(f.picker(),"POST","/counts",count(c,next,6,"COUNTED")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");next=submit(next);assertEquals("DISPUTED",next.get("state"));var review=inventory(f.manager(),"GET","/sessions/"+first.get("id")+"/review?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");next=inventory(f.manager(),"POST","/sessions/approve",Map.of("storeId",f.store(),"sessionId",next.get("id"),"selectedRoundId",first.get("id"),"expectedRevision",next.get("revision"),"requestKey",key(),"reviewToken",review.get("reviewToken"),"reason","Premier comptage retenu après contrôle des deux observations")).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");inventory(f.manager(),"POST","/sessions/apply",Map.of("storeId",f.store(),"sessionId",next.get("id"),"expectedRevision",next.get("revision"),"requestKey",key())).then().statusCode(200);total(c.account,5);QuarkusTransaction.requiringNew().run(()->{assertEquals(2,InventoryCountObservation.count("line.session.handlingOrder.id",c.order));var values=InventoryCountObservation.<InventoryCountObservation>list("line.session.handlingOrder.id=?1 order by id",c.order).stream().map(o->o.quantity.intValueExact()).toList();assertEquals(List.of(5,6),values);});}

 @Test void listAndDetailShowTheActualCounterEvenWithoutAPlanningAssignee(){var c=start();var detail=inventory(f.manager(),"GET","/"+c.order+"?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");assertEquals(((Number)c.session.get("employeeId")).longValue(),((Number)detail.get("employeeId")).longValue());assertNotNull(detail.get("employeeName"));var list=inventory(f.manager(),"GET","?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().<Map<String,Object>>getList("items");assertEquals(detail.get("employeeName"),list.stream().filter(v->((Number)v.get("id")).longValue()==c.order).findFirst().orElseThrow().get("employeeName"));}

 @Test void activitySummaryCountsObservationsOnceWithoutTurningUnknownIntoZero(){
  var c=start();var packet=count(c,c.session,7,"COUNTED");var session=inventory(f.picker(),"POST","/counts",packet).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");inventory(f.picker(),"POST","/counts",packet).then().statusCode(200);
  inventory(f.picker(),"POST","/counts",count(c,session,null,"UNKNOWN")).then().statusCode(200);
  var summary=given().auth().oauth2(f.picker()).get("/handling-orders/operator/consultation/summary?storeId="+f.store()).then().statusCode(200).extract().jsonPath();var rows=summary.<Map<String,Object>>getList("operations");var observation=rows.stream().filter(v->"COUNTED".equals(v.get("metric"))).findFirst().orElseThrow();assertEquals(0,new BigDecimal("7").compareTo(new BigDecimal(observation.get("quantity").toString())));assertEquals(1,((Number)observation.get("confirmedCommands")).intValue());total(c.account,10);
 }

 @Test void variantFactsDoNotRevealTheBlindInventoryReference(){
  QuarkusTransaction.requiringNew().run(()->{var p=com.intermarche.backoffice.domain.order.Product.<com.intermarche.backoffice.domain.order.Product>findById(f.product());p.characteristics="Taille M · noir";p.brand="Variante test";});
  var c=start();var lines=(List<Map<String,Object>>)c.session.get("lines");assertFalse(lines.isEmpty());
  assertEquals("Taille M · noir",lines.getFirst().get("characteristics"));assertEquals("Variante test",lines.getFirst().get("brand"));assertNull(lines.getFirst().get("referenceQuantity"));
 }

 @Test void locationObservationDoesNotRevealTheoreticalStockDuringBlindCounting(){var c=start();given().auth().oauth2(f.picker()).get("/field-operations/products/"+f.product()+"/location-stock?storeId="+f.store()+"&locationId="+f.location()).then().statusCode(409).body("code",org.hamcrest.Matchers.is("BLIND_INVENTORY"));given().auth().oauth2(f.manager()).get("/field-operations/products/"+f.product()+"/location-stock?storeId="+f.store()+"&locationId="+f.location()).then().statusCode(200);}
}
